ALTER TABLE gantt_memberships DROP CONSTRAINT IF EXISTS gantt_memberships_role_check;
ALTER TABLE gantt_memberships ADD CONSTRAINT gantt_memberships_role_check CHECK(role IN('owner','scheduler','editor','viewer','procurement'));
ALTER TABLE gantt_invitations DROP CONSTRAINT IF EXISTS gantt_invitations_role_check;
ALTER TABLE gantt_invitations ADD CONSTRAINT gantt_invitations_role_check CHECK(role IN('scheduler','editor','viewer','procurement'));
CREATE TABLE IF NOT EXISTS gantt_comments(id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id text NOT NULL,task_id text,author_id uuid NOT NULL REFERENCES gantt_users(id),body text NOT NULL,mentions uuid[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,FOREIGN KEY(organization_id,project_id) REFERENCES gantt_projects(organization_id,id));
CREATE TABLE IF NOT EXISTS gantt_notifications(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES gantt_organizations(id),user_id uuid NOT NULL REFERENCES gantt_users(id),message text NOT NULL,project_id text,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS gantt_notifications_user ON gantt_notifications(organization_id,user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS gantt_attachments(id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id text NOT NULL,task_id text,author_id uuid NOT NULL REFERENCES gantt_users(id),name text NOT NULL,mime text NOT NULL,size integer NOT NULL CHECK(size>0 AND size<=10000000),object_key text NOT NULL UNIQUE,storage text NOT NULL CHECK(storage IN('local','s3')),state text NOT NULL CHECK(state IN('pending','ready')),created_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,FOREIGN KEY(organization_id,project_id) REFERENCES gantt_projects(organization_id,id));
CREATE TABLE IF NOT EXISTS gantt_templates(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES gantt_organizations(id),name text NOT NULL,snapshot jsonb NOT NULL,created_by uuid NOT NULL REFERENCES gantt_users(id),created_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS gantt_entitlements(organization_id uuid PRIMARY KEY REFERENCES gantt_organizations(id),plan text NOT NULL DEFAULT 'community',state text NOT NULL DEFAULT 'active',features jsonb NOT NULL DEFAULT '{"projects":100,"exports":true,"attachments":true,"scenarios":true}',provider text NOT NULL DEFAULT 'community',updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS gantt_jobs(id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id text NOT NULL,actor_id uuid NOT NULL REFERENCES gantt_users(id),kind text NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'queued',result jsonb,error text,attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,project_id) REFERENCES gantt_projects(organization_id,id));
CREATE INDEX IF NOT EXISTS gantt_jobs_queued ON gantt_jobs(state,created_at);
CREATE TABLE IF NOT EXISTS gantt_recovery_codes(user_id uuid NOT NULL REFERENCES gantt_users(id),token_hash text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gantt_mfa(user_id uuid PRIMARY KEY REFERENCES gantt_users(id),secret_encrypted text NOT NULL,enabled boolean NOT NULL DEFAULT false,last_step bigint NOT NULL DEFAULT -1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gantt_oidc_identities(issuer text NOT NULL,subject text NOT NULL,user_id uuid NOT NULL REFERENCES gantt_users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(issuer,subject));
CREATE TABLE IF NOT EXISTS gantt_oidc_states(token_hash text PRIMARY KEY,verifier text NOT NULL,nonce text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS gantt_sections(organization_id uuid NOT NULL,project_id text NOT NULL,id text NOT NULL,parent_id text,data jsonb NOT NULL,version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,project_id,id),FOREIGN KEY(organization_id,project_id) REFERENCES gantt_projects(organization_id,id));
CREATE TABLE IF NOT EXISTS gantt_tasks(organization_id uuid NOT NULL,project_id text NOT NULL,id text NOT NULL,section_id text NOT NULL,parent_id text,data jsonb NOT NULL,version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,project_id,id),FOREIGN KEY(organization_id,project_id,section_id) REFERENCES gantt_sections(organization_id,project_id,id));
CREATE TABLE IF NOT EXISTS gantt_dependencies(id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id text NOT NULL,predecessor_id text NOT NULL,successor_id text NOT NULL,relation text NOT NULL CHECK(relation IN('FS','SS','FF','SF')),lag numeric NOT NULL,lag_unit text NOT NULL,version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,project_id,predecessor_id) REFERENCES gantt_tasks(organization_id,project_id,id) ON DELETE CASCADE,FOREIGN KEY(organization_id,project_id,successor_id) REFERENCES gantt_tasks(organization_id,project_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS gantt_project_entities(organization_id uuid NOT NULL,project_id text NOT NULL,id text NOT NULL,kind text NOT NULL,data jsonb NOT NULL,version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,project_id,kind,id),FOREIGN KEY(organization_id,project_id) REFERENCES gantt_projects(organization_id,id));
CREATE TABLE IF NOT EXISTS gantt_organization_settings(organization_id uuid PRIMARY KEY REFERENCES gantt_organizations(id),status_definitions jsonb NOT NULL DEFAULT '[]',version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
